def caesar(s, k):
    result = []
    for ch in s:
        if ch.islower():
            result.append(chr((ord(ch) - ord("a") + k) % 26 + ord("a")))
        elif ch.isupper():
            result.append(chr((ord(ch) - ord("A") + k) % 26 + ord("A")))
        else:
            result.append(ch)
    return "".join(result)
